 rows:(bet,level)=>Array.from({length:20},(_,i)=>{const multiplier=Math.round(0.95/Math.pow(1-CHANCES[level],i+1)*100)/100;return {step:i+1,multiplier,payout:Math.min(1000000,Math.round(bet*multiplier*100)/100)}}),
